using System.Globalization;
using System.Text;

namespace MintPlayer.Spark.Files;

/// <summary>
/// The display name of an uploaded file (#700 §3.3). It is never a path, a storage key or an attachment name: those are
/// generated by the server. It is still shown to users and sent back in <c>Content-Disposition</c>, so it is cleaned.
/// </summary>
public static class FileNameSanitizer
{
    /// <summary>The longest name kept, in characters (the extension is preserved when shortening).</summary>
    public const int MaxLength = 128;

    private const string Fallback = "file";

    private static readonly HashSet<string> ReservedWindowsNames = new(StringComparer.OrdinalIgnoreCase)
    {
        "CON", "PRN", "AUX", "NUL",
        "COM1", "COM2", "COM3", "COM4", "COM5", "COM6", "COM7", "COM8", "COM9",
        "LPT1", "LPT2", "LPT3", "LPT4", "LPT5", "LPT6", "LPT7", "LPT8", "LPT9",
    };

    public static string Sanitize(string? name)
    {
        if (string.IsNullOrWhiteSpace(name))
            return Fallback;

        var normalized = name.Normalize(NormalizationForm.FormC);

        // The last path segment, for either separator: a client never names a folder.
        var lastSeparator = normalized.LastIndexOfAny(['/', '\\']);
        if (lastSeparator >= 0)
            normalized = normalized[(lastSeparator + 1)..];

        var builder = new StringBuilder(normalized.Length);
        foreach (var rune in normalized.EnumerateRunes())
        {
            var category = Rune.GetUnicodeCategory(rune);
            // Control characters, and the format characters (bidi overrides such as U+202E, zero-width joiners) that
            // make "evil‮fdp.exe" display as "evilexe.pdf".
            if (category is UnicodeCategory.Control or UnicodeCategory.Format or UnicodeCategory.Surrogate
                or UnicodeCategory.PrivateUse or UnicodeCategory.OtherNotAssigned or UnicodeCategory.LineSeparator
                or UnicodeCategory.ParagraphSeparator)
                continue;
            if (rune.IsAscii && "<>:\"|?*".Contains((char)rune.Value))
            {
                builder.Append('_');
                continue;
            }
            builder.Append(rune.ToString());
        }

        // Windows drops trailing dots and spaces; leading dots make hidden files.
        var cleaned = builder.ToString().Trim().Trim('.').Trim();
        if (cleaned.Length == 0)
            return Fallback;

        var stem = Path.GetFileNameWithoutExtension(cleaned);
        if (ReservedWindowsNames.Contains(stem.TrimEnd()))
            cleaned = "_" + cleaned;

        return Shorten(cleaned);
    }

    /// <summary>
    /// <paramref name="name"/> (already sanitised) with the extension of the re-encoded image type: <c>cat.gif</c> becomes
    /// <c>cat.png</c> when the GIF was re-encoded as a PNG (M8). A name whose extension already fits is kept as it is.
    /// </summary>
    public static string WithExtensionFor(string name, string contentType)
    {
        var (extension, alternatives) = contentType switch
        {
            "image/png" => (".png", new[] { ".png" }),
            "image/jpeg" => (".jpg", new[] { ".jpg", ".jpeg", ".jfif" }),
            "image/webp" => (".webp", new[] { ".webp" }),
            _ => (null, Array.Empty<string>()),
        };
        if (extension is null || alternatives.Any(a => name.EndsWith(a, StringComparison.OrdinalIgnoreCase)))
            return name;
        var current = Path.GetExtension(name);
        var stem = current.Length > 0 ? name[..^current.Length] : name;
        return Shorten((stem.Length > 0 ? stem : Fallback) + extension);
    }

    private static string Shorten(string name)
    {
        var info = new StringInfo(name);
        if (info.LengthInTextElements <= MaxLength)
            return name;

        var extension = Path.GetExtension(name);
        if (extension.Length > 16)
            extension = string.Empty;
        var keep = MaxLength - extension.Length;
        return info.SubstringByTextElements(0, keep) + extension;
    }
}
